-- AECI-1534 (renumbered 0098 → 0100 by AECI-1543): private row threads (STAGE_2_ATTESTATIONS_SPEC.md §15.5, §15.8).
-- Generated by drizzle-kit, then edited by hand in two ways:
--   1. `claim_threads` is created first, so the file reads parent before child.
--      SQLite resolves an FK at write time, so the order changes nothing else.
--   2. Three COLUMN-level CHECKs on `claim_threads`, which drizzle-kit cannot see.
--      They are deliberately absent from `schema.ts`: a table-level `check()` there
--      would make a later `db:generate` render a recreate of this table, and its
--      DROP would cascade away every message and read marker
--      (`docs/migrations.md` §3.3a). `migration-0098.spec.ts` asserts they are in
--      the live DDL, so a regenerated recreate that drops them fails CI.
-- Pure CREATE TABLE / CREATE INDEX. No existing table is touched.
CREATE TABLE `claim_threads` (
	`id` text PRIMARY KEY NOT NULL,
	`claim_id` text,
	`vendor_a_id` text NOT NULL,
	`vendor_b_id` text NOT NULL CONSTRAINT "claim_threads_distinct_vendors_check" CHECK ("vendor_b_id" <> "vendor_a_id"),
	`anchor_snapshot` text,
	`closed_at` text CONSTRAINT "claim_threads_closed_pair_check" CHECK (("closed_at" IS NULL) = ("closed_reason" IS NULL)),
	`closed_reason` text CONSTRAINT "claim_threads_closed_reason_check" CHECK ("closed_reason" IN ('retired', 'withdrawn', 'claim_removed', 'not_attestable')),
	`help_requested_at` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`claim_id`) REFERENCES `claims`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`vendor_a_id`) REFERENCES `vendors`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`vendor_b_id`) REFERENCES `vendors`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `claim_threads_claim_key` ON `claim_threads` (`claim_id`) WHERE "claim_id" IS NOT NULL;--> statement-breakpoint
CREATE INDEX `claim_threads_vendor_a_idx` ON `claim_threads` (`vendor_a_id`);--> statement-breakpoint
CREATE INDEX `claim_threads_vendor_b_idx` ON `claim_threads` (`vendor_b_id`);--> statement-breakpoint
CREATE TABLE `claim_thread_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`thread_id` text NOT NULL,
	`author_profile_id` text,
	`author_vendor_id` text NOT NULL,
	`body` text NOT NULL,
	`created_at` text NOT NULL,
	`deleted_at` text,
	FOREIGN KEY (`thread_id`) REFERENCES `claim_threads`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`author_profile_id`) REFERENCES `profiles`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`author_vendor_id`) REFERENCES `vendors`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE INDEX `claim_thread_messages_thread_created_idx` ON `claim_thread_messages` (`thread_id`,`created_at`,`id`);--> statement-breakpoint
CREATE TABLE `claim_thread_reads` (
	`thread_id` text NOT NULL,
	`profile_id` text NOT NULL,
	`read_at` text NOT NULL,
	PRIMARY KEY(`thread_id`, `profile_id`),
	FOREIGN KEY (`thread_id`) REFERENCES `claim_threads`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`profile_id`) REFERENCES `profiles`(`id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
CREATE INDEX `claim_thread_reads_profile_idx` ON `claim_thread_reads` (`profile_id`);
